<script>
document.addEventListener('DOMContentLoaded',()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,els=document.querySelectorAll('[data-reveal]');if(reduced)els.forEach(e=>e.classList.add('show'));else{const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');io.unobserve(e.target)}}),{threshold:.12});els.forEach((e,i)=>{e.style.transitionDelay=`${i%3*90}ms`;io.observe(e)})}document.querySelectorAll('[data-tilt]').forEach(el=>{if(reduced)return;el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1100px) rotateX(${-y*7}deg) rotateY(${x*9}deg) translateY(-3px)`});el.addEventListener('pointerleave',()=>el.style.transform='')});const ci=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;let el=e.target,n=+el.dataset.count,s=performance.now();function tick(t){let p=Math.min((t-s)/1100,1);el.textContent=Math.round(n*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick);ci.unobserve(el)}));document.querySelectorAll('[data-count]').forEach(e=>ci.observe(e))});
</script>
